def toggle_bits(number):
    """
    Toggle only the first and last bits of the given number.

    Args:
    number (int): The number whose bits are to be toggled.

    Returns:
    int: The number with only the first and last bits toggled.
    """
    # Check if the number is odd or even
    if number % 2 == 0:
        # If even, toggle the first and last bits
        return (number << 1) | (number >> 1)
    else:
        # If odd, toggle the first and last bits
        return (number ^ (number - 1)) & ~(number - 1)

