def max_sublist_length(nums):
    """
    Find the maximum length of a contiguous subarray in a list of integers.

    :param nums: List of integers.
    :return: The length of the longest contiguous subarray.
    """
    if not nums:
        return 0

    max_length = 1
    current_length = 1

    for i in range(1, len(nums)):
        if nums[i] > nums[i - 1]:
            current_length += 1
        else:
            current_length = 1

        if current_length > max_length:
            max_length = current_length

    return max_length

