def sum_of_product_binomial_coefficients(n):
    """
    Calculate the sum of product of binomial coefficients for a given n.

    Args:
    n (int): The number of terms in the binomial expansion.

    Returns:
    int: The sum of product of binomial coefficients.
    """
    if n == 0:
        return 1
    else:
        return sum([binom(n, i) * binom(n - i, i) for i in range(n + 1)])

